/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var isArray = require( '@stdlib/assert/is-array' );
var isNumber = require( '@stdlib/assert/is-number' ).isPrimitive;
var format = require( '@stdlib/string/format' );


// FUNCTIONS //

/**
* Validate the array.
*
* @private
* @param {Array} value - array of axises data
* @throws {TypeError}
*/
function validate( value ) {
	var i;

	if ( !isArray( value) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a Array. Value: `%s`.', 'axis-data', value ) );
	}
	if ( value.length > 0 ) {
		for ( i = 0; i < value.length; i++ ) {
			if ( !isNumber( value[ i ][ 1 ] ) ) {
				throw new TypeError( format( 'invalid assignment. `%s` data 1st value need to  be the number indicate the height of the category. Value: `%s`.', 'axis-data', value[ i ] ) );
			}
		}
	}
}


// MAIN //

/**
* Sets the rendering mode.
*
* @private
* @param {Array} value - Array of data
* @throws {TypeError} must be a boolean
*/
function set( value ) {
	var i;

	validate( value );
	this._data = value;
}


// EXPORTS //

module.exports = set;
